/**
 * Core argument / Full paper toggle (D-025).
 *
 * Reads AutoGenerated/core_paper.json (the core manifest) and, once the paper
 * is rendered, shows either the manifest sections only, in manifest order and
 * each headed by its role sentence (Core), or the whole paper with the
 * non-core sections badged "supplementary" (Full). The choice is remembered
 * in localStorage (try/catch: it may be unavailable). Default: Core.
 */
(function () {
    'use strict';

    var KEY = 'pm.paper.view';
    var PREFIXES = ['/AutoGenerated/', 'AutoGenerated/', './AutoGenerated/',
                    '../AutoGenerated/', '../../AutoGenerated/'];

    function readMode() {
        try {
            var v = window.localStorage.getItem(KEY);
            return v === 'full' ? 'full' : 'core';
        } catch (e) { return 'core'; }
    }

    function saveMode(mode) {
        try { window.localStorage.setItem(KEY, mode); } catch (e) { /* ignore */ }
    }

    async function loadManifest() {
        for (var i = 0; i < PREFIXES.length; i++) {
            try {
                var r = await fetch(PREFIXES[i] + 'core_paper.json');
                if (r.ok) return await r.json();
            } catch (e) { /* try next prefix */ }
        }
        return null;
    }

    function el(tag, cls, text) {
        var n = document.createElement(tag);
        if (cls) n.className = cls;
        if (text) n.textContent = text;
        return n;
    }

    function sectionMap(container) {
        var map = {};
        container.querySelectorAll('.paper-section[data-section-key]').forEach(function (s) {
            map[s.getAttribute('data-section-key')] = s;
        });
        return map;
    }

    function decorate(map, manifest) {
        var core = {};
        manifest.core.forEach(function (c, i) { core[c.id] = { role: c.role, order: i + 1 }; });
        Object.keys(map).forEach(function (id) {
            var s = map[id];
            if (core[id]) {
                var role = el('p', 'pm-core-role', core[id].role);
                var h = s.querySelector('.section-header');
                if (h && h.nextSibling) h.parentNode.insertBefore(role, h.nextSibling);
                else s.appendChild(role);
            } else {
                var badge = el('span', 'pm-supp-badge', 'supplementary');
                var t = s.querySelector('.section-title');
                if (t) t.appendChild(badge);
                s.setAttribute('data-supplementary', '1');
            }
        });
        return core;
    }

    function apply(mode, container, map, core) {
        var abstract = container.querySelector('.paper-abstract');
        var toc = container.querySelector('.paper-toc, .toc-section');
        var parent = container.querySelector('.paper-sections');
        document.body.setAttribute('data-paper-view', mode);
        if (parent) {
            parent.style.display = 'flex';
            parent.style.flexDirection = 'column';
        }
        Object.keys(map).forEach(function (id) {
            var s = map[id];
            var c = core[id];
            s.style.display = (mode === 'core' && !c) ? 'none' : '';
            s.style.order = (mode === 'core' && c) ? String(c.order) : '';
        });
        if (toc) toc.style.display = mode === 'core' ? 'none' : '';
        if (abstract) abstract.style.display = '';
        container.querySelectorAll('.appendix-nav, .paper-appendix-nav').forEach(function (n) {
            n.style.display = mode === 'core' ? 'none' : '';
        });
    }

    function addStyle() {
        var st = el('style');
        st.textContent =
            '.pm-core-bar{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;margin:0 0 1rem;font-size:.9rem}' +
            '.pm-core-bar button{padding:.45rem .9rem;border:1px solid var(--border-light,#ccc);border-radius:999px;background:transparent;color:inherit;cursor:pointer;font:inherit}' +
            '.pm-core-bar button[aria-pressed="true"]{background:var(--accent-primary,#5b4bd6);color:#fff;border-color:transparent}' +
            '.pm-core-bar .pm-core-count{color:var(--text-muted,#666)}' +
            '.pm-core-role{margin:.25rem 0 .75rem;font-style:italic;color:var(--text-muted,#666)}' +
            '.pm-supp-badge{display:inline-block;margin-left:.6rem;padding:.1rem .5rem;border-radius:999px;font-size:.7rem;font-weight:500;vertical-align:middle;border:1px solid var(--border-light,#ccc);color:var(--text-muted,#666)}';
        document.head.appendChild(st);
    }

    function buildBar(manifest, onPick) {
        var t = manifest.totals;
        var bar = el('div', 'pm-core-bar');
        bar.setAttribute('role', 'group');
        bar.setAttribute('aria-label', 'Paper view');
        var core = el('button', '', 'Core argument');
        var full = el('button', '', 'Full paper');
        core.type = 'button';
        full.type = 'button';
        core.addEventListener('click', function () { onPick('core'); });
        full.addEventListener('click', function () { onPick('full'); });
        var count = el('span', 'pm-core-count');
        bar.appendChild(core);
        bar.appendChild(full);
        bar.appendChild(count);
        bar._set = function (mode) {
            core.setAttribute('aria-pressed', String(mode === 'core'));
            full.setAttribute('aria-pressed', String(mode === 'full'));
            count.textContent = mode === 'core'
                ? t.core_sections + ' sections, ' + t.core_words.toLocaleString() + ' words'
                : t.all_sections + ' sections, ' + t.all_words.toLocaleString() + ' words';
        };
        return bar;
    }

    async function init(containerId) {
        var container = document.getElementById(containerId || 'paper-content');
        if (!container || container.getAttribute('data-core-toggle')) return false;
        var manifest = await loadManifest();
        if (!manifest || !manifest.core) {
            console.warn('PMCoreToggle: core_paper.json not found; showing the full paper');
            return false;
        }
        container.setAttribute('data-core-toggle', '1');
        addStyle();
        var map = sectionMap(container);
        var core = decorate(map, manifest);
        var bar = buildBar(manifest, function (mode) {
            saveMode(mode);
            bar._set(mode);
            apply(mode, container, map, core);
        });
        container.insertBefore(bar, container.firstChild);
        var mode = readMode();
        bar._set(mode);
        apply(mode, container, map, core);
        return true;
    }

    window.PMCoreToggle = { init: init };
})();
